from rules import resolve


def solve(data):
    versions = resolve(data)
    if versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': versions}

import re


def _bounds(value):
    if value is None:
        return None, None
    if isinstance(value, dict):
        return (value.get('min', value.get('minimum', value.get('min_version'))),
                value.get('max', value.get('maximum', value.get('max_version'))))
    if isinstance(value, (list, tuple)):
        if len(value) >= 2:
            return value[0], value[1]
        if len(value) == 1:
            return value[0], value[0]
    if isinstance(value, int):
        return value, value
    return None, None


def _parse_dependency(dep):
    if isinstance(dep, str):
        match = re.fullmatch(r'\s*([A-Za-z0-9_.-]+)\s*(.*?)\s*', dep)
        if not match:
            return dep.strip(), (None, None)
        name, expr = match.groups()
        lo = hi = None
        for op, number in re.findall(r'(>=|<=|==|>|<)\s*(-?\d+)', expr):
            number = int(number)
            if op == '==':
                lo = number if lo is None else max(lo, number)
                hi = number if hi is None else min(hi, number)
            elif op == '>=':
                lo = number if lo is None else max(lo, number)
            elif op == '>':
                lo = number + 1 if lo is None else max(lo, number + 1)
            elif op == '<=':
                hi = number if hi is None else min(hi, number)
            else:
                hi = number - 1 if hi is None else min(hi, number - 1)
        return name, (lo, hi)

    if isinstance(dep, dict):
        name = dep.get('name', dep.get('package'))
        if name is None and len(dep) == 1:
            name, value = next(iter(dep.items()))
            return name, _bounds(value)
        if name is None:
            return None, (None, None)
        if isinstance(dep.get('version'), int):
            version = dep['version']
            return name, (version, version)
        if 'range' in dep or 'versions' in dep:
            return name, _bounds(dep.get('range', dep.get('versions')))
        return name, (dep.get('min', dep.get('minimum', dep.get('min_version'))),
                      dep.get('max', dep.get('maximum', dep.get('max_version'))))

    if isinstance(dep, (list, tuple)) and dep:
        if len(dep) == 2:
            return dep[0], _bounds(dep[1])
        if len(dep) >= 3:
            return dep[0], (dep[1], dep[2])
        return dep[0], (None, None)
    return None, (None, None)


def _within(version, bounds):
    lo, hi = bounds
    return (lo is None or version >= lo) and (hi is None or version <= hi)


def _intersect(left, right):
    lo, hi = left
    other_lo, other_hi = right
    if other_lo is not None:
        lo = other_lo if lo is None else max(lo, other_lo)
    if other_hi is not None:
        hi = other_hi if hi is None else min(hi, other_hi)
    if lo is not None and hi is not None and lo > hi:
        return None
    return lo, hi


def _active_dependency(dep, features):
    if isinstance(dep, dict):
        feature = dep.get('feature')
        if feature and feature not in features:
            return False
    return True


def _acyclic(assigned, features):
    graph = {name: [] for name in assigned}
    for name, (_, row) in assigned.items():
        for dep in row.get('deps', []) or []:
            if not _active_dependency(dep, features):
                continue
            dep_name, _ = _parse_dependency(dep)
            graph[name].append(dep_name)

    state = {}

    def visit(name):
        state[name] = 1
        for neighbor in graph[name]:
            if neighbor not in graph:
                return False
            if state.get(neighbor) == 1:
                return False
            if state.get(neighbor, 0) == 0 and not visit(neighbor):
                return False
        state[name] = 2
        return True

    return all(state.get(name, 0) != 0 or visit(name) for name in graph)


def resolve(data):
    packages = data['packages']
    names = sorted(packages)
    rows = {name: packages[name] for name in names}
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', []) or []

    initial = {}
    for name, value in data.get('roots', {}).items():
        if name not in rows:
            return None
        initial[name] = _bounds(value)

    best_vector = None
    best = None

    def visit(assigned, constraints):
        nonlocal best_vector, best

        upper = tuple(
            assigned[name][1]['version'] if name in assigned else
            max([-1] + [row['version'] for row in rows[name]])
            for name in names
        )
        if best_vector is not None and upper <= best_vector:
            return

        pending = sorted(name for name in constraints if name not in assigned)
        if not pending:
            if not _acyclic(assigned, features):
                return
            vector = tuple(assigned[name][1]['version'] if name in assigned else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: item[1]['version'] for name, item in assigned.items()}
            return

        name = pending[0]
        forbidden = blocked.get(name, ()) or ()
        choices = [row for row in rows[name]
                   if _within(row['version'], constraints[name])
                   and row['version'] not in forbidden
                   and (name not in pins or row['version'] == pins[name])]
        choices.sort(key=lambda row: row['version'], reverse=True)

        for row in choices:
            new_assigned = dict(assigned)
            new_assigned[name] = (None, row)
            new_constraints = dict(constraints)
            valid = True
            for dep in row.get('deps', []) or []:
                if not _active_dependency(dep, features):
                    continue
                dep_name, bounds = _parse_dependency(dep)
                if dep_name not in rows:
                    valid = False
                    break
                combined = _intersect(
                    new_constraints.get(dep_name, (None, None)), bounds)
                if combined is None:
                    valid = False
                    break
                if dep_name in new_assigned and not _within(
                        new_assigned[dep_name][1]['version'], combined):
                    valid = False
                    break
                new_constraints[dep_name] = combined
            if valid:
                visit(new_assigned, new_constraints)

    visit({}, initial)
    return best
